#!/usr/bin/env python3
# Orbit Store TV app - Writes src/orbit/icons.{hpp,cpp} from flatten.html's output.
# usage: icons.py <dumped dom.html> <src/orbit directory>
import html, json, re, sys

dom = open(sys.argv[1], encoding="utf-8").read()
data = json.loads(html.unescape(re.search(r'<pre id="out">(.*?)</pre>', dom, re.S).group(1)))
out = sys.argv[2]

def cname(name):
    return re.sub(r"([A-Z])", lambda m: "_" + m.group(1).lower(), name)

points, runs, icons = [], [], []
for name, icon in data.items():
    first = len(runs)
    for run in icon["runs"]:
        runs.append((len(points) // 2, len(run)))
        for x, y in run:
            points += [x, y]
    icons.append((name, first, len(runs) - first, icon["filled"]))

HPP_HEAD = '// Orbit Store TV app - Line icons for Crossbar, Cinema and Panorama.\n// SPDX-License-Identifier: GPL-3.0-or-later\n//\n// The interface designs\' icon set (24 px grid, round strokes), flattened to\n// polylines by tools/icons/generate.sh.\n\n#pragma once\n\n#include "gfx/draw_list.hpp"\n\n#include <cstdint>\n\nnamespace orbit::icons\n{\n\nenum class Icon : std::uint8_t\n{\n'
HPP_TAIL = '    count,\n};\n\n// Draws icon centred on (cx, cy), size px square; stroke is in grid units (24 = size).\nvoid draw(hui::gfx::DrawList &list, Icon icon, float cx, float cy, float size, hui::gfx::Color ink,\n          float stroke = 1.8f);\n\n} // namespace orbit::icons\n'
CPP_HEAD = '// Orbit Store TV app - Line icons for Crossbar, Cinema and Panorama.\n// SPDX-License-Identifier: GPL-3.0-or-later\n//\n// Generated by tools/icons/generate.sh from tools/icons/icons.json: each icon\'s\n// outline sampled and simplified on a 24 px grid. Don\'t edit by hand.\n\n#include "orbit/icons.hpp"\n\n#include <cmath>\n#include <vector>\n\nnamespace orbit::icons\n{\n\nnamespace\n{\n\nconst float kPoints[] = {\n'
CPP_RUNS = '};\n\nstruct Run\n{\n    std::uint16_t first; // point index\n    std::uint16_t count;\n};\nconst Run kRuns[] = {\n'
CPP_ICONS = '};\n\nstruct Entry\n{\n    std::uint16_t first_run;\n    std::uint8_t runs;\n    bool filled;\n};\nconst Entry kIcons[] = {\n'
CPP_TAIL = '\n};\n\n} // namespace\n\nvoid draw(hui::gfx::DrawList &list, Icon icon, float cx, float cy, float size, hui::gfx::Color ink,\n          float stroke)\n{\n    const int at = static_cast<int>(icon);\n    if (at < 0 || at >= static_cast<int>(Icon::count))\n        return;\n    const Entry &entry = kIcons[at];\n    const float scale = size / 24.0f;\n    const float x0 = cx - size * 0.5f;\n    const float y0 = cy - size * 0.5f;\n    const float width = stroke * scale;\n    // Opaque ink overlaps freely; translucent ink must not double up at joints.\n    const bool solid = ink.a >= 0.98f;\n    std::vector<float> outline;\n    for (int r = 0; r < entry.runs; ++r)\n    {\n        const Run &run = kRuns[entry.first_run + r];\n        const float *p = kPoints + 2 * run.first;\n        if (entry.filled)\n        {\n            outline.clear();\n            for (int i = 0; i < run.count; ++i)\n            {\n                outline.push_back(x0 + p[2 * i] * scale);\n                outline.push_back(y0 + p[2 * i + 1] * scale);\n            }\n            list.polygon(outline.data(), run.count, ink);\n            continue;\n        }\n        for (int i = 0; i + 1 < run.count; ++i)\n        {\n            const float ax = x0 + p[2 * i] * scale;\n            const float ay = y0 + p[2 * i + 1] * scale;\n            const float bx = x0 + p[2 * i + 2] * scale;\n            const float by = y0 + p[2 * i + 3] * scale;\n            if (solid)\n            {\n                list.line(ax, ay, bx, by, width, ink);\n                continue;\n            }\n            const float length = std::hypot(bx - ax, by - ay);\n            if (length <= 0.0f)\n                continue;\n            list.rotated_rect({(ax + bx) * 0.5f - length * 0.5f, (ay + by) * 0.5f - width * 0.5f, length, width},\n                              0.0f, std::atan2(by - ay, bx - ax), ink);\n            if (i + 2 < run.count)\n            {\n                // A sharp corner gets a round join.\n                const float cx2 = x0 + p[2 * i + 4] * scale;\n                const float cy2 = y0 + p[2 * i + 5] * scale;\n                const float turn = std::fabs(std::remainder(std::atan2(cy2 - by, cx2 - bx) - std::atan2(by - ay, bx - ax), 6.2831853f));\n                if (turn > 0.5f)\n                    list.circle(bx, by, width * 0.5f, ink);\n            }\n        }\n    }\n}\n\n} // namespace orbit::icons\n'

with open(out + "/icons.hpp", "w") as f:
    f.write(HPP_HEAD + "".join(f"    {cname(n)},\n" for n in data) + HPP_TAIL)
with open(out + "/icons.cpp", "w") as f:
    rows = ["    " + ", ".join(f"{p:.2f}f" for p in points[i:i + 12]) + "," for i in range(0, len(points), 12)]
    f.write(CPP_HEAD + "\n".join(rows) + "\n" + CPP_RUNS)
    f.write("\n".join(f"    {{{a}, {b}}}," for a, b in runs) + "\n" + CPP_ICONS)
    f.write("\n".join(f"    {{{a}, {b}, {'true' if fl else 'false'}}}, // {n}" for n, a, b, fl in icons) + CPP_TAIL)
print(f"{len(icons)} icons, {len(points) // 2} points")
